(() => {
'use strict';const $=s=>document.querySelector(s),core=window.PiecewiseLesson,NS='http://www.w3.org/2000/svg';
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}const number=x=>String(x).replace('.','{,}');const point=(x,y)=>[250+x*50,350-y*50];
function condition(b){if(b.lo===b.hi)return `x=${b.lo}`;return Number.isFinite(b.hi)?`x${b.hc?'\\le':'<'}${b.hi}`:`x${b.lc?'\\ge':'>'}${b.lo}`;}
function graph(q,x,result){const host=$('#piecewise-branches');host.replaceChildren();const endpoints=new Map();for(const b of q.branches){if(b.lo<b.hi){const lo=Math.max(-4,b.lo),hi=Math.min(4,b.hi),path=document.createElementNS(NS,'path');let d='';for(let i=0;i<=160;i++){const sx=lo+(hi-lo)*i/160,[px,py]=point(sx,b.fn(sx));d+=(i?'L':'M')+px.toFixed(2)+' '+py.toFixed(2);}path.setAttribute('d',d);path.setAttribute('fill','none');path.setAttribute('stroke',b.color);path.setAttribute('stroke-width','3');host.append(path);}for(const [edge,closed] of [[b.lo,b.lc],[b.hi,b.hc]]){if(!Number.isFinite(edge))continue;const y=b.fn(edge),key=edge+':'+y,previous=endpoints.get(key);if(!previous||closed)endpoints.set(key,{x:edge,y,closed,color:b.color});}}
for(const e of endpoints.values()){const circle=document.createElementNS(NS,'circle'),[px,py]=point(e.x,e.y);circle.setAttribute('cx',px);circle.setAttribute('cy',py);circle.setAttribute('r','6');circle.setAttribute('fill',e.closed?e.color:'#fafaf5');circle.setAttribute('stroke',e.color);circle.setAttribute('stroke-width','2.5');host.append(circle);}const trial=$('#piecewise-trial');trial.style.display=result.status==='defined'?'':'none';if(result.status==='defined'){const [px,py]=point(x,result.value);trial.setAttribute('cx',px);trial.setAttribute('cy',py);}$('#piecewise-plot').setAttribute('aria-label',`Grafik fungsi per bagian. Masukan uji ${x}; ${result.status==='defined'?'keluaran '+result.value:'tidak terdefinisi'}. Lingkaran kosong tidak termasuk dan penuh termasuk.`);}
function draw(){const q=core.examples.find(q=>q.id===$('#piecewise-example').value),x=Number($('#piecewise-input').value),result=core.evaluate(q,x);$('#piecewise-output').value=String(x).replace('.',',');math($('#piecewise-rule'),q.tex);math($('#piecewise-domain'),`D_f=${q.domain}`);$('#branch-status').replaceChildren(...q.branches.map((b,i)=>{const card=document.createElement('div');card.className='branch-card'+(result.indices.includes(i)?' active':'');card.style.setProperty('--branch-color',b.color);const title=document.createElement('p');title.textContent=`Cabang ${i+1}: ${result.indices.includes(i)?'dipakai':'tidak dipakai'}`;const formula=document.createElement('span');formula.dataset.tex=condition(b);card.append(title,formula);return card;}));math($('#piecewise-value'),result.status==='defined'?`f(${number(x)})=${number(result.value)}`:String.raw`f(${number(x)})\quad\text{tidak terdefinisi}`);$('#piecewise-feedback').textContent=result.status==='defined'?`Masukan ${String(x).replace('.',',')} memenuhi syarat cabang ${result.indices[0]+1}. Gunakan rumus pada cabang itu; hasilnya ${String(result.value).replace('.',',')}.`:`Masukan ${String(x).replace('.',',')} tidak termasuk domain yang dinyatakan. Tidak ada keluaran fungsi di titik itu; ini bukan berarti keluarannya nol.`;graph(q,x,result);}
$('#piecewise-example').addEventListener('change',()=>{$('#piecewise-input').value=core.examples.find(q=>q.id===$('#piecewise-example').value).cut;draw();});$('#piecewise-input').addEventListener('input',draw);for(const [id,offset] of [['piecewise-left',-.25],['piecewise-boundary',0],['piecewise-right',.25]])$('#'+id).addEventListener('click',()=>{$('#piecewise-input').value=core.examples.find(q=>q.id===$('#piecewise-example').value).cut+offset;draw();});$('#piecewise-reset').addEventListener('click',()=>{$('#piecewise-example').value='jump';$('#piecewise-input').value=1;draw();});draw();
function boundary(){const mode=$('#boundary-rules').value,rule=core.boundary(mode),result=core.evaluate(rule,1),left=mode==='overlap'?'\\le':'<',right=mode==='gap'?'>':'\\ge';math($('#boundary-rule-equation'),`g(x)=\\begin{cases}x+1,&x${left}1\\3,&x${right}1\\end{cases}`);$('#boundary-rule-feedback').textContent=result.status==='defined'?'Pada masukan satu, hanya baris kedua berlaku dan keluarannya tiga. Semua masukan real memperoleh tepat satu keluaran.':result.status==='ambiguous'?'Pada masukan satu, kedua baris berlaku tetapi menghasilkan dua dan tiga. Karena ada dua keluaran berbeda, aturan ini tidak mendefinisikan fungsi pada seluruh bilangan real.':'Pada masukan satu, tidak ada baris yang berlaku. Karena domain dimaksud mencakup satu, aturannya belum lengkap. Jika domain diubah menjadi semua real selain satu, kedua cabang ini dapat menjadi fungsi pada domain tersebut.';}
$('#boundary-rules').addEventListener('change',boundary);boundary();
const questions=[
[String.raw`f(0)=?`,[String.raw`1`,String.raw`3`,String.raw`4`],0,'Masukan nol kurang dari satu, sehingga gunakan rumus masukan ditambah satu.'],
[String.raw`f(1)=?`,[String.raw`2`,String.raw`3`,String.raw`5`],1,'Masukan satu memenuhi syarat lebih dari atau sama dengan satu. Baris kedua memberi tiga.'],
[String.raw`h(x)=\begin{cases}-x,&x<0\\x,&x\ge0\end{cases}\quad h(-2)=?`,[String.raw`-2`,String.raw`0`,String.raw`2`],2,'Masukan negatif dua memilih baris pertama. Negatif dari negatif dua adalah dua.'],
[String.raw`g(x)=\begin{cases}x+1,&x\ne1\\5,&x=1\end{cases}\quad g(1)=?`,[String.raw`2`,String.raw`5`,String.raw`\text{Tidak terdefinisi}`],1,'Baris nilai khusus berlaku tepat pada satu. Nilai dari rumus di sekitar titik tidak menggantikan nilai khusus itu.'],
[String.raw`\text{Syarat mana memasukkan }x=1?`,[String.raw`x<1`,String.raw`x>1`,String.raw`x\ge1`],2,'Tanda lebih dari atau sama dengan memasukkan batasnya. Kedua tanda ketat tidak.'],
[String.raw`\text{Domain }\mathbb R,\quad x<1\ \text{atau}\ x>1`,[String.raw`\text{Ada celah di satu}`,String.raw`\text{Semua masukan tercakup}`],0,'Masukan satu masih anggota domain yang dinyatakan tetapi tidak memenuhi kedua syarat. Aturan perlu dilengkapi atau domain diubah.'],
[String.raw`x=1\quad\text{mendapat keluaran }2\ \text{dan }3`,[String.raw`\text{Fungsi yang sah}`,String.raw`\text{Bukan fungsi}`],1,'Satu masukan tidak boleh diberi dua keluaran berbeda. Yang dilarang bukan jumlah rumusnya, melainkan ketidakpastian keluaran.'],
[String.raw`C(1{,}5)=?`,[String.raw`1`,String.raw`4`,String.raw`5`],1,'Gunakan model biaya pada bacaan: tiga ditambah dua kali selisih satu setengah dan satu. Hasil total empat unit.']
];const solved=new Set();questions.forEach(([tex,options,answer,reason],i)=>{const box=document.createElement('fieldset'),legend=document.createElement('legend'),num=document.createElement('span'),formula=document.createElement('span');num.dataset.noEquation='';num.textContent=`Latihan ${i+1}: `;formula.dataset.tex=tex;legend.append(num,formula);box.append(legend);options.forEach((option,j)=>{const label=document.createElement('label'),radio=document.createElement('input'),copy=document.createElement('span');radio.type='radio';radio.name=`piecewise-q${i}`;radio.value=String(j);copy.dataset.tex=option;label.append(radio,copy);box.append(label);});const button=document.createElement('button');button.type='button';button.textContent='Periksa jawaban';const feedback=document.createElement('p');feedback.setAttribute('role','status');button.addEventListener('click',()=>{const selected=box.querySelector('input:checked');if(!selected){feedback.textContent='Pilih satu jawaban terlebih dahulu.';return;}const ok=Number(selected.value)===answer;if(ok)solved.add(i);feedback.textContent=(ok?'Tepat. ':'Belum tepat. ')+reason;feedback.className=ok?'correct':'incorrect';$('#piecewise-progress').textContent=`${solved.size} dari 8 latihan pernah dijawab tepat.`;});box.addEventListener('change',()=>{feedback.textContent='Jawaban berubah. Periksa kembali untuk melihat tanggapan.';feedback.className='';});box.append(button,feedback);$('#piecewise-questions').append(box);});$('#piecewise-progress').textContent='0 dari 8 latihan pernah dijawab tepat.';
try{$('#piecewise-reflection').value=localStorage.getItem('fondasi-piecewise-reflection')||'';}catch{$('#piecewise-save').textContent='Catatan belum dapat dimuat. Salin bila diperlukan.';}$('#piecewise-reflection').addEventListener('input',()=>{try{localStorage.setItem('fondasi-piecewise-reflection',$('#piecewise-reflection').value);$('#piecewise-save').textContent='Catatan tersimpan di peramban ini.';}catch{$('#piecewise-save').textContent='Catatan belum dapat disimpan. Salin bila diperlukan.';}});
})();
